UPDATE products SET blurb = 'The Covington 18 Inch Heavy Duty Slab Saw is a welded-steel slab saw with a six-speed power feed, automatic shut-off and a quick-return system.

An over-running clutch adjusts from soft to hard rock, and the powder-coated chassis weighs 325 lb. A 9 in vise, motor and an A-Series Signature blade are included.', features = '["A-Series Signature Blade included", "9\\" vise included", "Powder coated, heavy welded steel chassis", "6-speed power feed with automatic shut-off", "Quick return system", "Over-running clutch, soft to hard rock", "8\\" cross feed capacity without re-clamping", "One piece arbor and flange", "Heavy-duty neoprene sealed ball bearings, greased for life"]', included = '["9\\" vise", "Motor", "Covington\'s Best Diamond Blade (A-Series Signature Blade)"]', specs = '{"Weight": "325 lb"}', warranty = NULL WHERE id = 'covington-18-inch-heavy-duty-slab-saw';
UPDATE products SET blurb = 'The Covington Large Basic Wet Belt Sander is a build-your-own wet belt sander that takes 3 x 41-1/2 in belts.

The work area is unobstructed, belts change quickly, and the back plate adjusts. The hood, base and bearing support are powder-coated, and the bearings are shielded, double sealed and greased for life. Manufacturer\'s warranty applies.', features = '["Build-your-own style", "Unobstructed access to work area", "Quick change belt system", "3\\" x 41-1/2\\" belts", "Powder coated hood, base, and bearing support", "Shielded bearings, double sealed, greased for life", "Adjustable back plate"]', included = '[]', specs = '{"Belt size": "3\\" x 41-1/2\\""}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-large-basic-wet-belt-sander';
UPDATE products SET blurb = 'The Covington 36 Inch Slab Saw is Covington\'s largest slab saw, a 1,200 lb machine that runs on 220V/60Hz only.

It has a heavy welded steel chassis, six-speed power feed with automatic shut-off, quick-return system, an over-running clutch for soft to hard rock and 8 in of cross-feed capacity. The arbor and flange are one piece. A vise, motor and Covington Platinum blade are included.', features = '["220V, 60Hz only", "Powder coated, heavy welded steel chassis", "6-speed power feed with automatic shut-off", "Quick return system", "Over-running clutch, soft to hard rock", "8\\" cross feed capacity", "One-piece arbor and flange", "Neoprene-sealed, lifetime-greased ball bearings"]', included = '["Vise", "Motor", "Covington Platinum Blade"]', specs = '{"Weight": "1,200 lb"}', warranty = NULL WHERE id = 'covington-36-inch-slab-saw';
UPDATE products SET blurb = 'The Covington Basic Wet Belt Sander is a build-your-own wet belt sander for 3 x 24 in belts.

