UPDATE products SET blurb = 'The Covington 8 Inch Grinder Polisher is a diamond-equipped grinding and polishing unit with a 1/2 hp motor and speed control adjustable in 8 rpm steps.

It includes two 8 x 1-1/2 in metal-bond diamond wheels (100 and 220 grit), two 3 x 8 in diamond belts (325 and 1,200 grit), an 8 in aluminum head with leather disc and an 8 in expandable drum. A 5 gram syringe of 50,000 mesh diamond compound and a 2 oz bottle of extender fluid are supplied. The footprint is 36 x 24 in and it weighs 200 lb.', features = '["Two 8\\" x 1-1/2\\" metal-bond diamond grinding wheels (100g & 220g)", "Two 3\\" x 8\\" diamond belts (325g & 1,200g)", "8\\" aluminum head with leather disc", "8\\" expandable drum", "Speed control with 8 rpm changes", "1/2 hp heavy duty motor", "Rustproof aluminum-topped Lam-I-Cushion base", "Heavy-duty neoprene sealed ball bearings, greased for life"]', included = '["5-gram syringe of 50,000 mesh diamond compound", "2-ounce bottle of extender fluid", "Sample kit (polish powder, brush, dop sticks, wax)", "Book about using diamond abrasives", "Instructions"]', specs = '{"Footprint": "36\\" x 24\\"", "Weight": "200 lb"}', warranty = NULL WHERE id = 'covington-8-inch-grinder-polisher-diamond';
UPDATE products SET blurb = 'The Covington Heavy Duty Grinder Polisher is a quiet, high-torque machine with a 1/2 hp motor that accepts 6 in and 8 in wheels.

The arbor, pans and hoods are heavy-duty powder-coated aluminum, and the shaft is a turned, ground and polished 1 x 18 in piece. It works with 8 in aluminum heads and expandable drums and rides on neoprene-sealed ball bearings. Flanges, nuts, drive pulley, V-belt, belt guard, water valves and drains are included. The footprint is 22 x 24 in.', features = '["1/2 hp high-torque motor", "Runs quietly", "Heavy-duty powder coated aluminum arbor, pans, hoods", "1\\" x 18\\" turned, ground & polished shaft", "Accommodates 6\\" & 8\\" wheels", "8\\" aluminum heads and expandable drums", "Neoprene sealed ball bearings, greased for life"]', included = '["Flanges", "Nuts", "Drive pulley", "V-belt", "Belt guard", "Water valves", "Drains"]', specs = '{"Footprint": "22\\" x 24\\""}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-heavy-duty-grinder-polisher';
UPDATE products SET blurb = 'The Covington Vertical Glass Beveler has a 1/2 hp motor and takes 6 in, 8 in and 10 in wheels.

An adjustable sponge bench limits splash, the back plate has a spray nozzle, and the tank sides come off to make wheel changes easy. Neoprene-sealed ball bearings are greased for life and the base is rustproof. It has a belt guard and manufacturer\'s warranty.', features = '["Adjustable sponge bench minimizes splash", "Back plate with spray nozzle", "Fits 6\\", 8\\", and 10\\" wheels", "Removable tank sides for easy wheel change", "Neoprene sealed ball bearings, greased for life", "Rustproof base", "1/2 hp motor", "Belt guard"]', included = '[]', specs = '{}', warranty = 'Manufacturer\'s warranty' WHERE id = 'covington-vertical-glass-beveler';
UPDATE products SET blurb = 'The Covington Felt Polishing Dome polishes the inside edges of glassware and, used with cerium oxide, produces an optically clear finish.

It screws onto Covington flat lap machines with the supplied 5/8-11 threaded brass adapter. The dome is about 4-1/2 in across at the base and 1-1/2 in tall.', features = '["For polishing interior edges of glassware", "Works with cerium oxide for optically clear finish", "Threaded brass adapter for flat lap machines"]', included = '["5/8\\"-11 threaded brass adapter"]', specs = '{"Base diameter": "~4-1/2\\"", "Height": "1-1/2\\""}', warranty = NULL WHERE id = 'covington-felt-polishing-dome';
